typedef unsigned int size_t;

void *operator new(size_t, unsigned int, const char *, int);
#define NEW new(0, __FILE__, __LINE__)

class stringx {
public:
  stringx();
  stringx(const char *, int = -1);
  stringx(const stringx &);
  ~stringx();
};

class color32 {
public:
  unsigned char b, g, r, a;
  color32(unsigned char rr, unsigned char gg, unsigned char bb, unsigned char aa)
      : b(bb), g(gg), r(rr), a(aa) {}
};

class Font {
public:
  enum HORIZJUST { HORIZJUST_LEFT, HORIZJUST_CENTER, HORIZJUST_RIGHT };
  enum VERTJUST { VERTJUST_TOP, VERTJUST_CENTER, VERTJUST_BOTTOM };
};

class TextString {
public:
  char pad[76];
  virtual void changeScale(const float);

  TextString(Font *f, stringx t, float x1, float y1, int z1, float s,
             const Font::HORIZJUST horizJust,
             const Font::VERTJUST vertJust, color32 col) {
    cons(f, t, x1, y1, z1, s, horizJust, vertJust, false, col);
  }

protected:
  virtual void cons(Font *, stringx, float, float, int, float,
                    const Font::HORIZJUST, const Font::VERTJUST, bool,
                    color32);
};

class FEMenuEntry;

class FEMultiMenu {
public:
  char pad[352];
  virtual void Load();
};

struct FrontEndManager {
  Font font_body;
};

extern FrontEndManager frontendmanager;

#define PHONE_TEXT_COLOR color32(49, 67, 48, 255)
#define PHONE_SCREEN_TOP 73
#define PHONE_SCREEN_RIGHT 502
#define PHONE_TEXT_SIZE 0.666f
#define PHONE_TOGGLE_TEXT_SIZE 0.555f
#define MAX_CHEATS_PER_SCREEN 2
#define PHONE_LIST_VERT_SPACING 32
#define PHONE_TOGLE_TOP_OFFSET 18

class CheatCodeMenu : public FEMultiMenu {
private:
  FEMenuEntry *cheats[MAX_CHEATS_PER_SCREEN];
  int menu_entry_cheat_index[MAX_CHEATS_PER_SCREEN];
  void *sys;
  int next_down, next_up;
  TextString *toggle_state[MAX_CHEATS_PER_SCREEN];
  void *arrow_up;
  void *arrow_down;

public:
  virtual void Load();

private:
  void SetPQIndices();
};

void CheatCodeMenu::Load()
{
	FEMultiMenu::Load();
	SetPQIndices();

	// Initialize all the cheat menu items to be NULL
	for(int i = 0; i < MAX_CHEATS_PER_SCREEN; i++)
	{
		cheats[i] = NULL;
		menu_entry_cheat_index[i] = -1;
		toggle_state[i] = NEW TextString(&frontendmanager.font_body, "", PHONE_SCREEN_RIGHT, 
		                                 PHONE_SCREEN_TOP + PHONE_TOGLE_TOP_OFFSET + PHONE_LIST_VERT_SPACING * i, 
		                                 0, PHONE_TEXT_SIZE, Font::HORIZJUST_RIGHT, 
		                                 Font::VERTJUST_TOP, PHONE_TEXT_COLOR);
		toggle_state[i]->changeScale(PHONE_TOGGLE_TEXT_SIZE*1.5f);
	}
}
